// THE CLASS: resolves ALL three conflicts using different strategies
package com.bank.compliance.service;

import com.bank.compliance.dto.ComplianceResponse;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service
@Slf4j
public class TradingBankComplianceService implements RBICompliant, SEBICompliant {

    // ═══ CONFLICT 1: generateReport() — FIX: COMBINE BOTH ═══
    @Override
    public String generateReport() {
        // Uses InterfaceName.super.method() to call BOTH defaults
        String rbiReport = RBICompliant.super.generateReport();
        String sebiReport = SEBICompliant.super.generateReport();

        log.info("[CONFLICT RESOLVED] generateReport() — combined both regulators");
        return "DUAL COMPLIANCE REPORT:\n  → " + rbiReport + "\n  → " + sebiReport;
    }

    // ═══ CONFLICT 2: calculatePenalty() — FIX: DELEGATE TO ONE (SEBI is stricter) ═══
    @Override
    public BigDecimal calculatePenalty(int violations) {
        log.info("[CONFLICT RESOLVED] calculatePenalty() — delegating to SEBI (stricter)");
        return SEBICompliant.super.calculatePenalty(violations);
        // Deliberately chose SEBI because securities penalties are harsher
    }

    // ═══ CONFLICT 3: getAuditScore() — FIX: OWN IMPLEMENTATION ═══
    @Override
    public int getAuditScore() {
        // Custom logic: average of both + bonus for dual compliance
        int rbiScore = RBICompliant.super.getAuditScore();      // 85
        int sebiScore = SEBICompliant.super.getAuditScore();    // 78
        int average = (rbiScore + sebiScore) / 2;                // 81
        int dualBonus = 5;                                       // bonus for being dual-compliant

        log.info("[CONFLICT RESOLVED] getAuditScore() — custom: avg({},{}) + bonus {} = {}",
            rbiScore, sebiScore, dualBonus, average + dualBonus);
        return average + dualBonus;  // 86
    }

    // ═══ NON-CONFLICTING: these are inherited normally ═══
    // getKYCStatus() → inherited from RBICompliant (no conflict)
    // getMarginStatus() → inherited from SEBICompliant (no conflict)

    public ComplianceResponse getFullCompliance(int violations) {
        return new ComplianceResponse(
            generateReport(),
            calculatePenalty(violations),
            getAuditScore(),
            "generateReport=COMBINED | calculatePenalty=SEBI_DELEGATE | getAuditScore=CUSTOM_AVG"
        );
    }
}
