@RequiredArgsConstructor
public class ComplianceController {

    private final TradingBankComplianceService complianceService;

    @GetMapping("/report")
    public ComplianceResponse fullReport(@RequestParam(defaultValue = "2") int violations) {
        return complianceService.getFullCompliance(violations);
    }

    @GetMapping("/kyc")
    public Map<String, String> kycStatus() {
        // Non-conflicting — inherited from RBICompliant
        return Map.of("kyc", complianceService.getKYCStatus());
    }

    @GetMapping("/margin")
    public Map<String, String> marginStatus() {
        // Non-conflicting — inherited from SEBICompliant
        return Map.of("margin", complianceService.getMarginStatus());
    }
}
