package com.bank.compliance.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class DiamondConflictTest {

    // ═══ Test conflict resolution strategies ═══

    @Test
    void shouldCombineBothReports() {
        TradingBankComplianceService bank = new TradingBankComplianceService();
        String report = bank.generateReport();
        assertThat(report).contains("RBI Compliance Report");
        assertThat(report).contains("SEBI Compliance Report");
        assertThat(report).startsWith("DUAL COMPLIANCE REPORT");
    }

    @Test
    void shouldDelegateToSEBIForPenalty() {
        TradingBankComplianceService bank = new TradingBankComplianceService();
        BigDecimal penalty = bank.calculatePenalty(3);
        // SEBI: 25000 × 3 = 75000 (not RBI's 10000 × 3 = 30000)
        assertThat(penalty).isEqualByComparingTo("75000");
    }

    @Test
    void shouldUseCustomAverageForAuditScore() {
        TradingBankComplianceService bank = new TradingBankComplianceService();
        int score = bank.getAuditScore();
        // avg(85, 78) + 5 bonus = 81 + 5 = 86
        assertThat(score).isEqualTo(86);
    }

    @Test
    void shouldInheritNonConflictingDefaults() {
        TradingBankComplianceService bank = new TradingBankComplianceService();
        assertThat(bank.getKYCStatus()).contains("KYC Compliant");      // from RBI
        assertThat(bank.getMarginStatus()).contains("Margin Requirements"); // from SEBI
    }

    // ═══ Test Rule 2: sub-interface wins ═══

    @Test
    void subInterfaceWinsOverSuperInterface() {
        // EnhancedRBICompliant extends RBICompliant → more specific → wins
        class EnhancedBank implements EnhancedRBICompliant {}
        EnhancedBank bank = new EnhancedBank();
        assertThat(bank.generateReport()).contains("Enhanced RBI Report");
        // NOT "RBI Compliance Report" — sub-interface wins!
    }

    // ═══ Test Rule 1: class always wins ═══

    @Test
    void classAlwaysWinsOverInterfaceDefault() {
        class OverridingBank implements RBICompliant {
            @Override
            public String generateReport() { return "Bank's own report"; }
        }
        OverridingBank bank = new OverridingBank();
        assertThat(bank.generateReport()).isEqualTo("Bank's own report");
        // Class override wins over RBICompliant.super default
    }
}
